    private List<ShipmentDto>? shipments;
    private bool isLoading = true;
    private bool showCreateForm;
    private bool isCreating;
    private string filterText = string.Empty;
    private string filterStatus = string.Empty;
    private string? createError;
    private ShipmentDto newShipment = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch
        {
            shipments = null;
        }
        finally
        {
            isLoading = false;
        }
    }

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrEmpty(filterText) ||
             s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
             s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
             s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrEmpty(filterStatus) || s.Status == filterStatus));

    private void ToggleCreateForm()
    {
        showCreateForm = !showCreateForm;
        createError = null;
        if (showCreateForm)
            newShipment = new ShipmentDto { EstimatedDelivery = DateTime.Today.AddDays(7) };
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.TrackingNumber) ||
            string.IsNullOrWhiteSpace(newShipment.Origin) ||
            string.IsNullOrWhiteSpace(newShipment.Destination))
        {
            createError = "Tracking number, origin, and destination are required.";
            return;
        }

        isCreating = true;
        createError = null;
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            showCreateForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            createError = $"Failed to create shipment: {ex.Message}";
        }
        finally
        {
            isCreating = false;
        }
    }

    private async Task UpdateStatus(int id, string status)
    {
        try
        {
            await ShipmentService.UpdateStatusAsync(id, status);
            await LoadShipments();
        }
        catch
        {
            // Reload to show current state
            await LoadShipments();
        }
    }

    private static string FormatStatus(string status) => status switch
    {
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => status
    };

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "InTransit" => "bg-info text-dark",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Delayed" => "bg-danger",
        _ => "bg-secondary"
    };
}
