        {
            searchInput = TrackingNumber;
            await SearchShipment();
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(searchInput)) return;

        isLoading = true;
        searched = true;
        lastSearched = searchInput.Trim();

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(lastSearched);
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string FormatStatus(string status) => status switch
    {
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => status
    };

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "InTransit" => "bg-info text-dark",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Delayed" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "InTransit" => "bg-info",
        "OutForDelivery" => "bg-warning",
        "Delivered" => "bg-success",
        "Delayed" => "bg-danger progress-bar-striped progress-bar-animated",
        _ => "bg-secondary"
    };

    private static int GetProgressPercent(string status) => status switch
    {
        "Pending" => 10,
        "InTransit" => 45,
        "OutForDelivery" => 75,
        "Delivered" => 100,
        "Delayed" => 45,
        _ => 0
    };
