    </div>
}

@if (shipment is not null)
{
    <div class="card shadow-sm">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h4 class="mb-0">📦 @shipment.TrackingNumber</h4>
            <span class="badge fs-6 @GetStatusBadgeClass(shipment.Status)">@FormatStatus(shipment.Status)</span>
        </div>
        <div class="card-body">
            <div class="row">
