                            {
                                @shipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")
                            }
                            else
                            {
                                <span class="text-muted">TBD</span>
                            }
                        </dd>
                        @if (shipment.DeliveredAt.HasValue)
                        {
                            <dt>Delivered At</dt>
                            <dd class="text-success fw-bold">@shipment.DeliveredAt.Value.ToString("MMM dd, yyyy h:mm tt")</dd>
                        }
                    </dl>
                </div>
            </div>

            <h5 class="mt-3">Shipment Progress</h5>
            <div class="progress" style="height: 30px;">
                <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                     role="progressbar"
                     style="width: @GetProgressPercent(shipment.Status)%"
                     aria-valuenow="@GetProgressPercent(shipment.Status)"
                     aria-valuemin="0" aria-valuemax="100">
                    @FormatStatus(shipment.Status)
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public string? TrackingNumber { get; set; }

    private string searchInput = string.Empty;
    private string lastSearched = string.Empty;
    private ShipmentDto? shipment;
    private bool isLoading;
    private bool searched;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchInput = TrackingNumber;
            await SearchShipment();
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(searchInput)) return;

        isLoading = true;
        searched = true;
        lastSearched = searchInput.Trim();

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(lastSearched);
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string FormatStatus(string status) => status switch
    {
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => status
    };

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "InTransit" => "bg-info text-dark",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Delayed" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "InTransit" => "bg-info",
        "OutForDelivery" => "bg-warning",
        "Delivered" => "bg-success",
        "Delayed" => "bg-danger progress-bar-striped progress-bar-animated",
        _ => "bg-secondary"
    };

    private static int GetProgressPercent(string status) => status switch
    {
        "Pending" => 10,
        "InTransit" => 45,
        "OutForDelivery" => 75,
        "Delivered" => 100,
        "Delayed" => 45,
        _ => 0
    };
}

