+@page "/shipments"
+@attribute [Authorize]
+@inject IShipmentService ShipmentService
+
+<PageTitle>Dispatcher Dashboard</PageTitle>
+
+<div class="d-flex justify-content-between align-items-center mb-3">
+    <h2>📋 Dispatcher Dashboard</h2>
+    <button class="btn btn-success" @onclick="ToggleCreateForm">
+        @(showCreateForm ? "Cancel" : "➕ New Shipment")
+    </button>
+</div>
+
+@if (showCreateForm)
+{
+    <div class="card mb-4 shadow-sm">
+        <div class="card-body">
+            <h5>Create New Shipment</h5>
+            <div class="row g-3">
+                <div class="col-md-4">
+                    <label class="form-label">Tracking Number</label>
+                    <input class="form-control" @bind="newShipment.TrackingNumber" placeholder="TRK-XXXX" />
+                </div>
+                <div class="col-md-4">
+                    <label class="form-label">Origin</label>
+                    <input class="form-control" @bind="newShipment.Origin" placeholder="City, State" />
+                </div>
+                <div class="col-md-4">
+                    <label class="form-label">Destination</label>
+                    <input class="form-control" @bind="newShipment.Destination" placeholder="City, State" />
+                </div>
+                <div class="col-md-4">
+                    <label class="form-label">Description</label>
+                    <input class="form-control" @bind="newShipment.Description" />
+                </div>
+                <div class="col-md-4">
+                    <label class="form-label">Customer Email</label>
+                    <input class="form-control" type="email" @bind="newShipment.CustomerEmail" />
+                </div>
+                <div class="col-md-4">
+                    <label class="form-label">Estimated Delivery</label>
+                    <input class="form-control" type="date" @bind="newShipment.EstimatedDelivery" />
+                </div>
+                <div class="col-12">
+                    <button class="btn btn-primary" @onclick="CreateShipment" disabled="@isCreating">
+                        @if (isCreating)
+                        {
+                            <span class="spinner-border spinner-border-sm me-1"></span>
+                        }
+                        Create Shipment
+                    </button>
+                </div>
+            </div>
+            @if (!string.IsNullOrEmpty(createError))
+            {
+                <div class="alert alert-danger mt-2">@createError</div>
+            }
+        </div>
+    </div>
+}
+
+<div class="row mb-3">
+    <div class="col-md-4">
+        <input class="form-control" placeholder="Filter by tracking #, destination..."
+               @bind="filterText" @bind:event="oninput" />
+    </div>
+    <div class="col-md-3">
+        <select class="form-select" @bind="filterStatus">
+            <option value="">All Statuses</option>
+            <option value="Pending">Pending</option>
+            <option value="InTransit">In Transit</option>
+            <option value="OutForDelivery">Out for Delivery</option>
+            <option value="Delivered">Delivered</option>
+            <option value="Delayed">Delayed</option>
+        </select>
+    </div>
+    <div class="col-md-2">
+        <button class="btn btn-outline-secondary w-100" @onclick="LoadShipments" disabled="@isLoading">
+            🔄 Refresh
+        </button>
+    </div>
+</div>
+
+@if (isLoading)
+{
+    <div class="text-center py-4">
+        <div class="spinner-border" role="status">
+            <span class="visually-hidden">Loading...</span>
+        </div>
+    </div>
+}
+else if (shipments is null)
+{
+    <div class="alert alert-danger">Failed to load shipments.</div>
+}
+else
+{
+    <div class="table-responsive">
+        <table class="table table-striped table-hover">
+            <thead class="table-dark">
+                <tr>
+                    <th>Tracking #</th>
+                    <th>Origin</th>
+                    <th>Destination</th>
+                    <th>Status</th>
+                    <th>Est. Delivery</th>
+                    <th>Actions</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var s in FilteredShipments)
+                {
+                    <tr>
+                        <td><strong>@s.TrackingNumber</strong></td>
+                        <td>@s.Origin</td>
+                        <td>@s.Destination</td>
+                        <td>
+                            <span class="badge @GetStatusBadgeClass(s.Status)">@FormatStatus(s.Status)</span>
+                        </td>
+                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</td>
+                        <td>
+                            @if (s.Status != "Delivered")
+                            {
+                                <select class="form-select form-select-sm d-inline-block" style="width: auto;"
+                                        @onchange="e => UpdateStatus(s.Id, e.Value?.ToString() ?? s.Status)">
+                                    <option value="" disabled selected>Change...</option>
+                                    <option value="Pending">Pending</option>
+                                    <option value="InTransit">In Transit</option>
+                                    <option value="OutForDelivery">Out for Delivery</option>
+                                    <option value="Delivered">Delivered</option>
+                                    <option value="Delayed">Delayed</option>
+                                </select>
+                            }
+                            else
+                            {
+                                <span class="text-success">✅ Complete</span>
+                            }
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+
+    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
+}
+
+@code {
+    private List<ShipmentDto>? shipments;
+    private bool isLoading = true;
+    private bool showCreateForm;
+    private bool isCreating;
+    private string filterText = string.Empty;
+    private string filterStatus = string.Empty;
+    private string? createError;
+    private ShipmentDto newShipment = new();
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        isLoading = true;
+        try
+        {
+            shipments = await ShipmentService.GetAllShipmentsAsync();
+        }
+        catch
+        {
+            shipments = null;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private IEnumerable<ShipmentDto> FilteredShipments =>
+        (shipments ?? []).Where(s =>
+            (string.IsNullOrEmpty(filterText) ||
+             s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
+             s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
+             s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
+            (string.IsNullOrEmpty(filterStatus) || s.Status == filterStatus));
+
+    private void ToggleCreateForm()
+    {
+        showCreateForm = !showCreateForm;
+        createError = null;
+        if (showCreateForm)
+            newShipment = new ShipmentDto { EstimatedDelivery = DateTime.Today.AddDays(7) };
+    }
+
+    private async Task CreateShipment()
+    {
+        if (string.IsNullOrWhiteSpace(newShipment.TrackingNumber) ||
+            string.IsNullOrWhiteSpace(newShipment.Origin) ||
+            string.IsNullOrWhiteSpace(newShipment.Destination))
+        {
+            createError = "Tracking number, origin, and destination are required.";
+            return;
+        }
+
+        isCreating = true;
+        createError = null;
+        try
+        {
+            await ShipmentService.CreateShipmentAsync(newShipment);
+            showCreateForm = false;
+            await LoadShipments();
+        }
+        catch (Exception ex)
+        {
+            createError = $"Failed to create shipment: {ex.Message}";
+        }
+        finally
+        {
+            isCreating = false;
+        }
+    }
+
+    private async Task UpdateStatus(int id, string status)
+    {
+        try
+        {
+            await ShipmentService.UpdateStatusAsync(id, status);
+            await LoadShipments();
+        }
+        catch
+        {
+            // Reload to show current state
+            await LoadShipments();
+        }
+    }
+
+    private static string FormatStatus(string status) => status switch
+    {
+        "InTransit" => "In Transit",
+        "OutForDelivery" => "Out for Delivery",
+        _ => status
+    };
+
+    private static string GetStatusBadgeClass(string status) => status switch
+    {
+        "Pending" => "bg-secondary",
+        "InTransit" => "bg-info text-dark",
+        "OutForDelivery" => "bg-warning text-dark",
+        "Delivered" => "bg-success",
+        "Delayed" => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
+

