148. @code {
149.     private List<ShipmentDto>? shipments;
150.     private bool isLoading = true;
151.     private bool showCreateForm;
152.     private bool isCreating;
153.     private string filterText = string.Empty;
154.     private string filterStatus = string.Empty;
155.     private string? createError;
156.     private ShipmentDto newShipment = new();
157. 
158.     protected override async Task OnInitializedAsync()
159.     {
160.         await LoadShipments();
161.     }
162. 
163.     private async Task LoadShipments()
164.     {
165.         isLoading = true;
166.         try
167.         {
168.             shipments = await ShipmentService.GetAllShipmentsAsync();
169.         }
170.         catch
171.         {
172.             shipments = null;
173.         }
174.         finally
175.         {
176.             isLoading = false;
177.         }
178.     }
179. 
180.     private IEnumerable<ShipmentDto> FilteredShipments =>
181.         (shipments ?? []).Where(s =>
182.             (string.IsNullOrEmpty(filterText) ||
183.              s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
184.              s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
185.              s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
186.             (string.IsNullOrEmpty(filterStatus) || s.Status == filterStatus));
187. 
188.     private void ToggleCreateForm()
189.     {
190.         showCreateForm = !showCreateForm;
191.         createError = null;
192.         if (showCreateForm)
193.             newShipment = new ShipmentDto { EstimatedDelivery = DateTime.Today.AddDays(7) };
194.     }
195. 
196.     private async Task CreateShipment()
197.     {
198.         if (string.IsNullOrWhiteSpace(newShipment.TrackingNumber) ||
199.             string.IsNullOrWhiteSpace(newShipment.Origin) ||
200.             string.IsNullOrWhiteSpace(newShipment.Destination))
201.         {
202.             createError = "Tracking number, origin, and destination are required.";
203.             return;
204.         }
205. 
206.         isCreating = true;
207.         createError = null;
208.         try
209.         {
210.             await ShipmentService.CreateShipmentAsync(newShipment);
211.             showCreateForm = false;
212.             await LoadShipments();
213.         }
214.         catch (Exception ex)
215.         {
216.             createError = $"Failed to create shipment: {ex.Message}";
217.         }
218.         finally
219.         {
220.             isCreating = false;
221.         }
222.     }
223. 
224.     private async Task UpdateStatus(int id, string status)
225.     {
226.         try
227.         {
228.             await ShipmentService.UpdateStatusAsync(id, status);
229.             await LoadShipments();
230.         }
231.         catch
232.         {
233.             // Reload to show current state
234.             await LoadShipments();
235.         }
236.     }
237. 
238.     private static string FormatStatus(string status) => status switch
239.     {
240.         "InTransit" => "In Transit",
241.         "OutForDelivery" => "Out for Delivery",
242.         _ => status
243.     };
244. 
245.     private static string GetStatusBadgeClass(string status) => status switch
246.     {
247.         "Pending" => "bg-secondary",
248.         "InTransit" => "bg-info text-dark",
249.         "OutForDelivery" => "bg-warning text-dark",
250.         "Delivered" => "bg-success",
251.         "Delayed" => "bg-danger",
252.         _ => "bg-secondary"
253.     };
254. }
255.

